-- Materialize the canonical metric catalog per real tenant using an active membership.
-- No service-role bypass and no change to the existing tenant RLS contract.
DO $$
DECLARE v_company uuid; v_user uuid;
BEGIN
  FOR v_company IN SELECT DISTINCT company_id FROM public.company_memberships WHERE is_active LOOP
    SELECT user_id INTO v_user FROM public.company_memberships WHERE company_id=v_company AND is_active ORDER BY is_default DESC,user_id LIMIT 1;
    IF v_user IS NULL THEN RAISE EXCEPTION 'METRIC_GOVERNANCE_TENANT_MEMBER_REQUIRED:%',v_company; END IF;
    PERFORM set_config('request.jwt.claim.sub',v_user::text,true);
    ON CONFLICT DO NOTHING;
  END LOOP;
END $$;
DELETE FROM public.metric_governance WHERE company_id IS NULL;
